async function init(){db=await new Promise((ok,no)=>{let r=indexedDB.open('observatorio-tron',1);r.onupgradeneeded=()=>r.result.createObjectStore('case');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);});const old=await new Promise((ok,no)=>{const r=db.transaction('case').objectStore('case').get('active');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);});if(old)state=old;migrateGraphSelection(state);restoreWorkspaceUI();for(const a of state.alerts){if(a.delivery?.status==='sending'){a.delivery.status='unknown';a.delivery.error='Envio interrompido: confirme no provedor antes de reenviar.';}}populateEmailConfig();$('#timezone').value=state.timezone;$('#auto').checked=state.auto;render();}
