async function setOnGraph(ids,on){state.graphSelected??={};for(const id of ids){if(on&&state.events[id])state.graphSelected[id]=true;else delete state.graphSelected[id];}renderRows();renderGraph();if(selection?.type==='event'&&ids.includes(selection.value)&&$('#eventOnGraph'))$('#eventOnGraph').checked=onGraph(selection.value);await save();}
