async function explodeEvents(ids){if(busy){toast('Aguarde a consulta terminar.');return false;}const targets=new Map();for(const id of ids){const t=explosionTarget(state.events[id]);if(!t)continue;const prev=targets.get(t.address);targets.set(t.address,{...t,start:Math.min(prev?.start??Infinity,t.start),events:[...(prev?.events||[]),id]});}if(!targets.size){toast('Nenhuma contraparte nova para explodir: os dois lados já estão no caso.');return false;}const free=10-state.addresses.filter(a=>a.expanded).length;if(targets.size>free){toast(`Limite de 10 expansões: restam ${Math.max(0,free)} e a seleção abriria ${targets.size}. Refine a seleção.`);return false;}for(const t of targets.values())state.addresses.push({address:t.address,label:nodeLabel(t.address),start:t.start,expanded:true,origin:t.events});state.graphSelected??={};for(const t of targets.values())for(const id of t.events)state.graphSelected[id]=true;await save();render();toast(`${targets.size} endereço${targets.size>1?'s':''} em expansão. As novas transações aparecem no explorador sem marcação; marque as que devem entrar no gráfico.`);sync();return true;}
function nodeLabel(address){return state.nodeLabels?.[address]??state.addresses.find(a=>a.address===address)?.label??'';}
async function setNodeLabel(address,value){const label=String(value).trim();if(label.length>60)throw Error('Use até 60 caracteres no nome.');state.nodeLabels??={};if(label)state.nodeLabels[address]=label;else delete state.nodeLabels[address];const monitored=state.addresses.find(a=>a.address===address);if(monitored)monitored.label=label;await save();}
const hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');
