let lastRequest=0;
async function api(path,body){await new Promise(r=>setTimeout(r,Math.max(0,350-(Date.now()-lastRequest))));lastRequest=Date.now();const response=await fetch('https://api.trongrid.io'+path,{method:body?'POST':'GET',headers:{...(key?{'TRON-PRO-API-KEY':key}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error(`TronGrid HTTP ${response.status}${response.status===429?' — limite de consultas; aguarde antes de tentar novamente':''}`);const data=await response.json();if(data.success===false||data.Error||data.error)throw Error(String(data.Error||data.error||'Resposta sem sucesso'));return data;}
