async function normalize(data,kind,owner){const out=[];if(kind==='trx'){for(const tx of data){if(!tx.ret?.length||tx.ret.some(r=>r.contractRet!=='SUCCESS'))continue;for(let i=0;i<(tx.raw_data?.contract||[]).length;i++){const c=tx.raw_data.contract[i];if(c.type!=='TransferContract')continue;const v=c.parameter.value;if(!Number.isSafeInteger(v.amount)||v.amount<=0)continue;out.push({id:tx.txID+':trx:'+i,hash:tx.txID,index:i,from:await b58(v.owner_address),to:await b58(v.to_address),asset:'TRX',value:String(v.amount),time:tx.block_timestamp,block:tx.blockNumber});}}}else{for(const hash of new Set(data.filter(t=>t.token_info?.address===USDT&&t.type==='Transfer').map(t=>t.transaction_id))){const r=await receipt(hash);if(r.receipt?.result&&r.receipt.result!=='SUCCESS')continue;for(let i=0;i<(r.log||[]).length;i++){const l=r.log[i];if(l.address?.toLowerCase().replace(/^41(?=.{40}$)/,'')!==CONTRACT||l.topics?.[0]?.toLowerCase()!==TRANSFER||l.topics.length!==3||!/^[0-9a-fA-F]{64}$/.test(l.data))continue;const from=await b58('41'+l.topics[1].slice(-40)),to=await b58('41'+l.topics[2].slice(-40));if(from!==owner&&to!==owner)continue;const value=BigInt('0x'+l.data).toString();if(value==='0')continue;out.push({id:hash+':log:'+i,hash,index:i,from,to,asset:'USDT',value,time:r.blockTimeStamp,block:r.blockNumber});}}}return out;}
function direction(e){const monitored=new Set(state.addresses.filter(a=>!a.expanded).map(a=>a.address));return monitored.has(e.from)?'out':monitored.has(e.to)?'in':'other';}
function evaluate(e){if(direction(e)==='other')return;const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:state.timezone,weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(e.time).map(x=>[x.type,x.value]));const time=parts.hour+':'+parts.minute,weekend=['Sat','Sun'].includes(parts.weekday);for(const r of state.rules){if(!r.enabled||r.asset!==e.asset||BigInt(e.value)<units(r.min)||(r.direction&&r.direction!==direction(e)))continue;if(r.days==='weekend'&&!weekend||r.days==='weekday'&&weekend)continue;if(r.from&&r.to){const inside=r.from<=r.to?time>=r.from&&time<=r.to:time>=r.from||time<=r.to;if(!inside)continue;}const id=r.id+':'+e.id;if(!state.alerts.some(a=>a.id===id))state.alerts.unshift({id,rule:r.name,event:e.id,created:Date.now(),recipient:r.recipient||'',snapshot:{...e},delivery:{status:r.recipient?'queued':'no_recipient'}});}}
async function collect(a,kind){a.streams??={};let s=a.streams[kind]??={since:a.start,initial:true};if(!s.window)s.window={from:Math.max(a.start,s.since-120000),to:Date.now()-60000,cursor:null};const w=s.window;if(w.to<w.from)return;for(let page=0;page<3;page++){const q=new URLSearchParams({limit:'50',only_confirmed:'true',order_by:'block_timestamp,asc',min_timestamp:String(w.from),max_timestamp:String(w.to)});if(kind==='usdt')q.set('contract_address',USDT);if(w.cursor)q.set('fingerprint',w.cursor);const path='/v1/accounts/'+a.address+'/transactions'+(kind==='usdt'?'/trc20':'')+'?'+q;const r=await api(path);if(!Array.isArray(r.data))throw Error('Resposta sem lista de transações');const events=await normalize(r.data,kind,a.address);preserve(path,r);for(const e of events){if(e.time<a.start||e.time>w.to)continue;if(!state.events[e.id]){state.events[e.id]=e;if(!s.initial&&!a.expanded){const before=new Set(state.alerts.map(a=>a.id));evaluate(e);const created=state.alerts.filter(a=>!before.has(a.id));if(created.length){await save();renderAlerts();for(const alert of created)await enqueueAlertEmail(alert.id);}}}}const next=r.meta?.fingerprint;if(!next||r.data.length===0){s.since=w.to;s.window=null;s.initial=false;s.updated=Date.now();await save();break;}if(next===w.cursor)throw Error('Paginação repetida; coleta interrompida para evitar lacunas');w.cursor=next;await save();}a.error=null;}
async function sync(){if(busy||!state.addresses.length)return;busy=true;$('#sync').disabled=true;$('#status').textContent='Consultando…';for(const a of state.addresses){for(const kind of ['trx','usdt']){try{await collect(a,kind);}catch(e){a.error=`${kind.toUpperCase()}: ${e.message}`;break;}}render();$('#status').textContent='Consultando…';}busy=false;$('#sync').disabled=false;state.last=Date.now();await save();render();}
function explorerFilters(){const f={graph:$('#graphFilter').value,asset:$('#explorerAsset').value,dir:$('#direction').value,query:$('#search').value.trim().toLowerCase(),op:$('#valueOp').value||'gt',value:null,from:null,to:null};if($('#dateFrom').value)f.from=zonedInput($('#dateFrom').value,state.timezone);if($('#dateTo').value)f.to=zonedInput($('#dateTo').value,state.timezone)+59999;if((f.from!==null&&!Number.isFinite(f.from))||(f.to!==null&&!Number.isFinite(f.to)))throw Error('Informe datas válidas.');if(f.from!==null&&f.to!==null&&f.from>f.to)throw Error('A data inicial do filtro deve ser anterior à final.');const value=$('#valueFilter').value.trim();if(value){if(!/^\d+([.,]\d{1,6})?$/.test(value))throw Error('Valor inválido: use até seis casas decimais.');f.value=units(value);}return f;}
