$('#graph').onpointerdown=e=>{if(e.button!==0||drag)return;suppressGraphClick=false;const target=e.target.closest('[data-visual]');if(!e.shiftKey&&!target&&e.target.closest('[data-edge]'))return;const p=graphPoint(e);if(!p)return;e.preventDefault?.();if(e.shiftKey){drag={mode:'rectangle',pointerId:e.pointerId,id:target?.dataset.visual,start:p,points:[{x:(p.x-pan.x)/zoom,y:(p.y-pan.y)/zoom}],client:{x:e.clientX,y:e.clientY},moved:false};}else{const id=target?.dataset.visual,node=id?positions.get(id):null,ids=id&&selectedNodes.has(id)?[...selectedNodes]:id?[id]:[];drag={mode:id?'nodes':'pan',pointerId:e.pointerId,id,start:p,origin:node?{...node}:{...pan},origins:new Map(ids.filter(id=>positions.has(id)).map(id=>[id,{...positions.get(id)}])),zoom,moved:false,client:{x:e.clientX,y:e.clientY}};}$('#graph').setPointerCapture(e.pointerId);$('#graph').classList.add('dragging');};
