function showNode(address){setInspectorOpen(true);selection={type:'node',value:address};renderRows();renderGraph();const a=state.addresses.find(a=>a.address===address);$('#detail').innerHTML=`<span class="eyebrow">ENDEREÇO TRON</span><h3>${esc(nodeLabel(address)||short(address))}</h3><p class="mono">${address}</p><p>${a?(a.expanded?'Expansão exploratória':'Monitorado')+' desde '+date(a.start):'Contraparte observada'}</p><a href="https://tronscan.org/#/address/${address}" target="_blank" rel="noopener noreferrer">Abrir no TronScan ↗</a><form id="nodeLabelForm" class="node-label-form"><label for="nodeLabelInput">Nome de referência do nó<input id="nodeLabelInput" name="label" maxlength="60" value="${esc(nodeLabel(address))}" placeholder="Ex.: Carteira de interesse" autocomplete="off"></label><button class="primary" type="submit">Salvar nome</button><p>Nome pessoal deste caso. Deixe vazio para remover.</p></form><hr>${!a?'<button class="primary" id="expandNode">↗ Expandir histórico</button><p>Expansão limitada a 10 endereços adicionais; não dispara alertas. Utiliza a data inicial mais antiga dos monitorados.</p>':''}<button id="funding">Consultar primeiro TRX direto</button><div id="fundingResult"></div>`;$('#nodeLabelForm').onsubmit=async e=>{e.preventDefault();const value=$('#nodeLabelInput').value;try{await setNodeLabel(address,value);render();if(selection?.type==='node'&&selection.value===address)showNode(address);toast(value.trim()?'Nome salvo no caso.':'Nome removido.');}catch(error){toast(error.message);}};if(!a)$('#expandNode').onclick=async()=>{if(busy)return toast('Aguarde a consulta terminar.');if(state.addresses.filter(a=>a.expanded).length>=10)return toast('Limite de 10 expansões atingido.');state.addresses.push({address,label:nodeLabel(address),start:Math.min(...state.addresses.filter(a=>!a.expanded).map(a=>a.start)),expanded:true});await save();render();sync();};$('#funding').onclick=async()=>{const box=$('#fundingResult');box.textContent='Consultando histórico independente…';try{const q=new URLSearchParams({limit:'200',only_confirmed:'true',only_to:'true',order_by:'block_timestamp,asc',search_internal:'false'});let cursor,found,scanned=0;for(let p=0;p<5;p++){if(cursor)q.set('fingerprint',cursor);const path='/v1/accounts/'+address+'/transactions?'+q;const r=await api(path);if(!Array.isArray(r.data))throw Error('Resposta inválida');preserve(path,r);scanned+=r.data.length;found=(await normalize(r.data,'trx',address)).filter(e=>e.to===address).sort((a,b)=>a.time-b.time)[0];cursor=r.meta?.fingerprint;if(found||!cursor)break;}await save();box.innerHTML=found?`<h3>Primeiro TRX direto localizado</h3><p>${date(found.time)}<br>${amount(found.value)} TRX<br>Origem: <span class="mono">${found.from}</span></p><a target="_blank" rel="noopener noreferrer" href="https://tronscan.org/#/transaction/${found.hash}">Ver transação ↗</a><p>Não inclui movimentos internos, ativação ou delegação. Não prova controle comum ou pagamento de uma taxa específica.</p>`:`<p>${cursor?'Busca parcial: limite de 1.000 registros.':'Nenhum recebimento direto de TRX localizado na consulta.'} ${scanned} registros examinados.</p>`;}catch(e){box.textContent='Consulta incompleta: '+e.message;}};}
function renderAlerts(){$('#alertBadge').textContent=state.alerts.length;$('#rules').innerHTML=state.rules.map(r=>`<div class="rule"><button data-rule="${r.id}">${r.enabled?'Pausar':'Ativar'}</button><b>${esc(r.name)}</b><p>${r.asset} · ${r.direction==='in'?'Entrada':r.direction==='out'?'Saída':'Qualquer direção'} ≥ ${amount(units(r.min))} · ${r.days==='all'?'Todos os dias':r.days==='weekend'?'Fim de semana':'Dias úteis'} ${r.from?esc(r.from)+'–'+esc(r.to):''} · ${r.enabled?'Ativa':'Pausada'}</p><p>E-mail: ${esc(r.recipient||'Sem destinatário — use Definir e-mail')}</p><button data-rule-email="${r.id}">Definir e-mail</button></div>`).join('')||'<p>Nenhuma regra cadastrada. Crie uma condição para acompanhar novos movimentos.</p>';$$('[data-rule-email]').forEach(b=>b.onclick=async()=>{const rule=state.rules.find(r=>r.id===b.dataset.ruleEmail);const recipient=prompt('E-mail de destino desta regra:',rule.recipient||state.emailConfig?.defaultRecipient||'');if(recipient===null)return;if(!validEmail(recipient.trim()))return toast('Informe um e-mail válido.');rule.recipient=recipient.trim();await save();renderAlerts();});$$('[data-rule]').forEach(b=>b.onclick=async()=>{state.rules.find(r=>r.id===b.dataset.rule).enabled^=1;await save();renderAlerts();});$('#alertList').innerHTML=state.alerts.map(a=>{const e=state.events[a.event];return `<div class="alert-item"><b>${esc(a.rule)}</b><p>${e?date(e.time)+' · '+amount(e.value)+' '+e.asset:'Evento removido do caso'}</p><span class="email-state ${['rejected','unknown'].includes(a.delivery?.status)?'error':''}">${esc(deliveryText(a))}</span>${a.recipient&&a.delivery?.status!=='accepted'?`<button data-retry-email="${esc(a.id)}">${a.delivery?.status==='unknown'?'Reenviar (pode duplicar)':'Enviar e-mail'}</button>`:''}${e?`<button data-alert="${e.id}">Inspecionar transação</button>`:''}</div>`;}).join('')||'<p>Nenhuma ocorrência. Regras avaliam apenas novos movimentos após a carga inicial.</p>';$$('[data-retry-email]').forEach(b=>b.onclick=()=>{const alert=state.alerts.find(a=>a.id===b.dataset.retryEmail);if(alert?.delivery?.status==='unknown'&&!confirm('O provedor pode ter recebido o envio anterior. Reenviar pode duplicar a mensagem. Continuar?'))return;enqueueAlertEmail(b.dataset.retryEmail,true);});$$('[data-alert]').forEach(b=>b.onclick=()=>{switchTab('monitor');showEvent(b.dataset.alert);});}
function validEmail(s){return typeof s==='string'&&s.length<=254&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);}
function emailConfigValid(c){return c&&['serviceId','templateId','publicKey'].every(k=>typeof c[k]==='string'&&/^[A-Za-z0-9_-]{1,200}$/.test(c[k]));}
function populateEmailConfig(){const c=state.emailConfig||{};for(const [id,key]of [['emailService','serviceId'],['emailTemplate','templateId'],['emailPublicKey','publicKey'],['emailDefault','defaultRecipient']])$('#'+id).value=c[key]||'';$('#emailConfigStatus').textContent=emailConfigValid(c)?'Configuração salva neste navegador. Envie um teste para confirmar o serviço e o template.':'Envio ainda não configurado. Preencha os identificadores públicos do EmailJS.';}
function deliveryText(a){const status=a.delivery?.status;const labels={queued:'Aguardando envio',pending_config:'E-mail não enviado: configure EmailJS',no_recipient:'E-mail não enviado: regra sem destinatário',sending:'Solicitando envio…',accepted:'Envio aceito pelo EmailJS (não confirma entrega na caixa de entrada)',rejected:'Envio recusado pelo provedor',unknown:'Resultado do envio não confirmado',imported:'Ocorrência importada: envio automático desativado para este registro'};return (labels[status]||'Ocorrência local, sem envio')+(a.recipient?' · '+a.recipient:'')+(a.delivery?.error?' · '+a.delivery.error:'');}
function emailParameters(a){const e=a.snapshot||state.events[a.event];if(!e)throw Error('Detalhes da transação indisponíveis.');return {to_email:a.recipient,subject:'Fenix Observatório — '+a.rule,message:['Regra: '+a.rule,'Valor: '+amount(e.value)+' '+e.asset,'Direção observada: '+({in:'Entrada',out:'Saída',other:'Movimento'})[direction(e)],'Transação: '+date(e.time)+' ('+state.timezone+')','Detecção: '+date(a.created),'Origem: '+e.from,'Destino: '+e.to,'Hash: '+e.hash,'Registro: '+e.id,'https://tronscan.org/#/transaction/'+e.hash].join('\n')};}
let emailQueue=Promise.resolve(),lastEmailRequest=0;
async function emailTransport(config,params){await new Promise(r=>setTimeout(r,Math.max(0,1100-(Date.now()-lastEmailRequest))));lastEmailRequest=Date.now();let response;try{response=await fetch('https://api.emailjs.com/api/v1.0/email/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({service_id:config.serviceId,template_id:config.templateId,user_id:config.publicKey,template_params:params}),signal:AbortSignal.timeout(30000)});}catch(e){return {status:'unknown',error:'Sem confirmação do provedor. Verifique o histórico do EmailJS antes de reenviar.'};}let text;try{text=(await response.text()).slice(0,500);}catch(e){return {status:'unknown',error:'O provedor não retornou confirmação legível; verifique antes de reenviar.'};}if(response.ok&&text.trim()==='OK')return {status:'accepted',acceptedAt:Date.now()};return {status:response.ok?'unknown':'rejected',error:'HTTP '+response.status+' — '+text};}
async function deliverAlertEmail(id,manual=false){const a=state.alerts.find(a=>a.id===id);if(!a||a.delivery?.status==='accepted'||a.delivery?.status==='sending')return;if(!manual&&!['queued'].includes(a.delivery?.status))return;if(!validEmail(a.recipient)){a.delivery={status:'no_recipient'};await save();renderAlerts();return;}if(!emailConfigValid(state.emailConfig)){a.delivery={status:'pending_config'};await save();renderAlerts();return;}const params=emailParameters(a);a.delivery={status:'sending',attemptAt:Date.now()};await save();renderAlerts();a.delivery=await emailTransport({...state.emailConfig},params);await save();renderAlerts();}
function enqueueAlertEmail(id,manual=false){emailQueue=emailQueue.catch(()=>{}).then(()=>deliverAlertEmail(id,manual)).catch(e=>toast('Não foi possível concluir o envio: '+e.message));return emailQueue;}
$('#emailConfigForm').onsubmit=async e=>{e.preventDefault();const config=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(config))config[k]=config[k].trim();if(!emailConfigValid(config)||config.defaultRecipient&&!validEmail(config.defaultRecipient))return toast('Verifique os identificadores públicos e o destinatário.');state.emailConfig=config;await save();populateEmailConfig();toast('Configuração salva. Use Enviar teste para validar.');};
$('#testEmail').onclick=async()=>{if(!emailConfigValid(state.emailConfig)||!validEmail(state.emailConfig.defaultRecipient))return toast('Salve a configuração com um destinatário padrão válido.');const button=$('#testEmail');button.disabled=true;const config={...state.emailConfig};emailQueue=emailQueue.catch(()=>{}).then(async()=>{const result=await emailTransport(config,{to_email:config.defaultRecipient,subject:'Fenix Observatório — teste de alerta',message:'Teste solicitado no painel em '+date(Date.now())+'. O envio de alertas está configurado quando esta mensagem chegar.'});$('#emailConfigStatus').textContent=result.status==='accepted'?'Teste aceito pelo EmailJS. Confira a caixa de entrada e o spam.':'Teste não confirmado: '+result.error;}).catch(e=>{$('#emailConfigStatus').textContent='Falha no teste: '+e.message;}).finally(()=>button.disabled=false);await emailQueue;};
function normalizeWorkspaceUI(value={}){value=value&&typeof value==='object'?value:{};return {explorerOpen:value.explorerOpen===true,explorerHeight:Number.isFinite(value.explorerHeight)?Math.max(200,Math.min(1600,value.explorerHeight)):340,inspectorOpen:value.inspectorOpen===true,sidebarCollapsed:value.sidebarCollapsed===true};}
function drawerMaximumHeight(){const total=$('#analysisWorkspace').getBoundingClientRect().height||window.innerHeight||900;return Math.max(200,total-180);}
function applyWorkspaceUI(){const workspace=$('#analysisWorkspace');workspace.classList.toggle('drawer-open',workspaceUI.explorerOpen);workspace.classList.toggle('inspector-closed',!workspaceUI.inspectorOpen);const height=Math.min(workspaceUI.explorerHeight,drawerMaximumHeight());workspace.style.setProperty('--drawer-height',height+'px');$('#explorerBody').hidden=!workspaceUI.explorerOpen;$('#drawerTools').hidden=!workspaceUI.explorerOpen;$('#explorerToggle').setAttribute('aria-expanded',String(workspaceUI.explorerOpen));$('#drawerArrow').textContent=workspaceUI.explorerOpen?'⌄':'⌃';$('#drawerResize').tabIndex=workspaceUI.explorerOpen?0:-1;$('#drawerResize').setAttribute('aria-valuenow',String(Math.round(height)));$('#drawerResize').setAttribute('aria-valuemin','200');$('#drawerResize').setAttribute('aria-valuemax',String(Math.round(drawerMaximumHeight())));$('#drawerMaximize').textContent=height>=drawerMaximumHeight()-2?'↙ Restaurar':'⛶ Ampliar';$('#inspectorToggle').textContent=workspaceUI.inspectorOpen?'×':'‹ Inspeção';$('#inspectorToggle').setAttribute('aria-expanded',String(workspaceUI.inspectorOpen));$('#inspectorToggle').setAttribute('aria-label',workspaceUI.inspectorOpen?'Recolher inspeção':'Abrir inspeção');document.body.classList.toggle('sidebar-collapsed',workspaceUI.sidebarCollapsed);$('#sidebarToggle').innerHTML=workspaceUI.sidebarCollapsed?'» <span>Expandir painel</span>':'« <span>Recolher painel</span>';$('#sidebarToggle').setAttribute('aria-expanded',String(!workspaceUI.sidebarCollapsed));}
function rememberWorkspaceUI(){state.workspaceUI={...workspaceUI};if(db)save().catch(()=>{});}
function restoreWorkspaceUI(){workspaceUI=normalizeWorkspaceUI(state.workspaceUI);applyWorkspaceUI();}
function setExplorerOpen(open){workspaceUI.explorerOpen=open;applyWorkspaceUI();rememberWorkspaceUI();}
function setInspectorOpen(open){workspaceUI.inspectorOpen=open;applyWorkspaceUI();rememberWorkspaceUI();}
function setDrawerHeight(height,persist=true){workspaceUI.explorerHeight=Math.max(200,Math.min(drawerMaximumHeight(),height));workspaceUI.explorerOpen=true;applyWorkspaceUI();if(persist)rememberWorkspaceUI();}
$('#explorerToggle').onclick=()=>setExplorerOpen(!workspaceUI.explorerOpen);$('#drawerClose').onclick=()=>setExplorerOpen(false);$('#drawerMaximize').onclick=()=>setDrawerHeight(workspaceUI.explorerHeight>=drawerMaximumHeight()-2?Math.min(340,drawerMaximumHeight()):drawerMaximumHeight());$('#inspectorToggle').onclick=()=>setInspectorOpen(!workspaceUI.inspectorOpen);$('#sidebarToggle').onclick=()=>{workspaceUI.sidebarCollapsed=!workspaceUI.sidebarCollapsed;applyWorkspaceUI();rememberWorkspaceUI();};
$('#drawerResize').onpointerdown=e=>{if(!workspaceUI.explorerOpen||e.button!==0)return;e.preventDefault();drawerDrag={pointerId:e.pointerId,y:e.clientY,height:Math.min(workspaceUI.explorerHeight,drawerMaximumHeight())};$('#drawerResize').setPointerCapture(e.pointerId);document.body.classList.add('drawer-resizing');};
$('#drawerResize').onpointermove=e=>{if(!drawerDrag||e.pointerId!==drawerDrag.pointerId)return;setDrawerHeight(drawerDrag.height+drawerDrag.y-e.clientY,false);};
function endDrawerResize(e){if(!drawerDrag||e.pointerId!==drawerDrag.pointerId)return;drawerDrag=null;document.body.classList.remove('drawer-resizing');rememberWorkspaceUI();if($('#drawerResize').hasPointerCapture(e.pointerId))$('#drawerResize').releasePointerCapture(e.pointerId);}
$('#drawerResize').onpointerup=endDrawerResize;$('#drawerResize').onpointercancel=endDrawerResize;$('#drawerResize').onlostpointercapture=endDrawerResize;
$('#drawerResize').onkeydown=e=>{if(!workspaceUI.explorerOpen)return;const step=e.shiftKey?80:30;if(e.key==='ArrowUp')setDrawerHeight(workspaceUI.explorerHeight+step);else if(e.key==='ArrowDown')setDrawerHeight(workspaceUI.explorerHeight-step);else if(e.key==='Home')setDrawerHeight(200);else if(e.key==='End')setDrawerHeight(drawerMaximumHeight());else return;e.preventDefault();};
function changeGraphZoom(factor){const previous=zoom;zoom=Math.max(.12,Math.min(4,zoom*factor));pan={x:500-(500-pan.x)*zoom/previous,y:260-(260-pan.y)*zoom/previous};renderGraph();}
$('#zoomIn').onclick=()=>changeGraphZoom(1.2);$('#zoomOut').onclick=()=>changeGraphZoom(1/1.2);window.addEventListener('resize',()=>applyWorkspaceUI());
function switchTab(name){if(name!=='monitor'&&graphFullPage)toggleGraphFullPage(false);$$('.tab').forEach(t=>t.hidden=t.id!==name);$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));}
$$('nav button').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
function openAddress(){if(busy)return toast('Aguarde a consulta terminar.');if(state.addresses.filter(a=>!a.expanded).length>=10)return toast('Limite inicial de 10 endereços monitorados.');$('#formZone').textContent=state.timezone;$('#addressDialog').showModal();}
$('#add').onclick=$('#emptyAdd').onclick=openAddress;$('#cancelAddress').onclick=()=>$('#addressDialog').close();
function zonedInput(value,zone){const nominal=new Date(value+'Z').getTime();let t=nominal;for(let i=0;i<3;i++){const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(t).map(x=>[x.type,x.value]));const represented=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);t+=nominal-represented;}return t;}
$('#addressForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),address=f.get('address').trim();if(!await validAddress(address))return toast('Endereço inválido: verifique o formato e o checksum Tron.');if(state.addresses.some(a=>a.address===address))return toast('Este endereço já está no caso.');const start=zonedInput(f.get('start'),state.timezone);if(!Number.isFinite(start)||start>Date.now())return toast('Informe uma data inicial válida, no passado.');const label=f.get('label').trim()||nodeLabel(address);if(label){state.nodeLabels??={};state.nodeLabels[address]=label;}state.addresses.push({address,label,start,expanded:false});await save();$('#addressDialog').close();e.target.reset();setExplorerOpen(true);render();toast('Transações coletadas aparecem no explorador. Marque as que devem entrar no gráfico.');sync();};
$('#addRule').onclick=()=>{$('#ruleForm').elements.namedItem('recipient').value=state.emailConfig?.defaultRecipient||'';$('#ruleDialog').showModal();};$('#cancelRule').onclick=()=>$('#ruleDialog').close();$('#ruleForm').onsubmit=async e=>{e.preventDefault();const r=Object.fromEntries(new FormData(e.target));if(!validEmail(r.recipient))return toast('Informe um e-mail de destino válido.');if(!!r.from!==!!r.to)return toast('Preencha os dois horários ou deixe ambos vazios.');if(!/^\d+([.,]\d{1,6})?$/.test(r.min))return toast('Valor inválido; use até seis casas decimais.');state.rules.push({...r,id:crypto.randomUUID(),enabled:true});await save();renderAlerts();$('#ruleDialog').close();e.target.reset();};$('#clearAlerts').onclick=async()=>{state.alerts=[];await save();renderAlerts();};
$('#graphDates').onclick=async()=>{state.graphDates=!state.graphDates;renderGraph();await save();};$('#sync').onclick=sync;$('#more').onclick=()=>{limit+=100;renderRows();};$('#fit').onclick=()=>{fitGraph();renderGraph();};$('#arrange').onclick=async()=>{positions.clear();state.graphPositions={};placeGraphNodes(scene?.nodes||[]);fitGraph();renderGraph();await save();};$('#clear').onclick=()=>{selection=null;for(const id of ['search','graphFilter','direction','asset','explorerAsset','dateFrom','dateTo','valueFilter'])$('#'+id).value='';$('#valueOp').value='gt';selectedNodes.clear();render();};$('#graphToggleAll').onchange=e=>{const events=visibleEvents();setOnGraph(events.map(v=>v.id),e.target.checked);toast(`${events.length} transaç${events.length>1?'ões':'ão'} ${e.target.checked?'marcada':'desmarcada'}${events.length>1?'s':''} no gráfico.`);};$('#explodeMarked').onclick=()=>{const ids=visibleEvents().filter(e=>onGraph(e.id)&&explosionTarget(e)).map(e=>e.id);const count=new Set(ids.map(id=>explosionTarget(state.events[id]).address)).size;if(ids.length&&confirm(`Explodir ${count} contraparte${count>1?'s':''} a partir de ${ids.length} transaç${ids.length>1?'ões marcadas':'ão marcada'}?`))explodeEvents(ids);};['#search','#graphFilter','#direction','#asset','#explorerAsset','#dateFrom','#dateTo','#valueOp','#valueFilter'].forEach(s=>$(s).addEventListener(['#search','#valueFilter'].includes(s)?'input':'change',()=>{limit=100;renderRows();if(s==='#asset')renderGraph();}));$('#apiKey').oninput=e=>key=e.target.value.trim();$('#timezone').onchange=async e=>{state.timezone=e.target.value;await save();render();};$('#auto').onchange=async e=>{state.auto=e.target.checked;await save();};
function download(name,content){const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('#export').onclick=async()=>{const payload=JSON.stringify(state);const hash=hex(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(payload)));download('fenix-observatorio-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({format:'observatorio-tron',sha256:hash,payload}));toast('Backup exportado com SHA-256. Não contém a chave de API.');};$('#import').onclick=()=>{if(busy)return toast('Aguarde a consulta terminar.');$('#file').click();};
function validateImport(s){if(s.version!==1||!Array.isArray(s.addresses)||s.addresses.length>20||s.addresses.filter(a=>!a.expanded).length>10||!s.events||typeof s.events!=='object'||!Array.isArray(s.rules)||!Array.isArray(s.raw)||!Array.isArray(s.alerts))throw Error('Estrutura incompatível');new Intl.DateTimeFormat('pt-BR',{timeZone:s.timezone});for(const a of s.addresses){if(!/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(a.address)||!Number.isFinite(a.start)||typeof a.label!=='string')throw Error('Endereço inválido no arquivo');}for(const [id,e]of Object.entries(s.events)){if(id!==e.id||! /^[a-f0-9]{64}:(trx|log):[0-9]+$/.test(e.id)||!/^[a-f0-9]{64}$/.test(e.hash)||!/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(e.from)||!/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(e.to)||!['TRX','USDT'].includes(e.asset)||!/^\d+$/.test(e.value)||!Number.isFinite(e.time)||!Number.isInteger(e.index))throw Error('Evento inválido');}for(const r of s.rules){if(!/^[a-f0-9-]{36}$/.test(r.id)||!/^\d+([.,]\d{1,6})?$/.test(r.min)||!['TRX','USDT'].includes(r.asset)||typeof r.name!=='string'||!['','in','out'].includes(r.direction)||!['all','weekend','weekday'].includes(r.days)||[r.from,r.to].some(t=>t&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(t)))throw Error('Regra inválida');}for(const r of s.rules)if(r.recipient&&!validEmail(r.recipient))throw Error('Destinatário inválido na regra');if(s.emailConfig&&!emailConfigValid(s.emailConfig))throw Error('Configuração EmailJS inválida');for(const a of s.alerts){if(a.recipient&&!validEmail(a.recipient))throw Error('Destinatário inválido');a.delivery={status:'imported'};delete a.snapshot;}if(s.nodeLabels!==undefined){if(!s.nodeLabels||typeof s.nodeLabels!=='object'||Array.isArray(s.nodeLabels))throw Error('Nomes de nós inválidos');for(const [address,label]of Object.entries(s.nodeLabels)){if(!/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(address)||typeof label!=='string'||label.length>60)throw Error('Nome de nó inválido');}for(const a of s.addresses)if(Object.hasOwn(s.nodeLabels,a.address))a.label=s.nodeLabels[a.address];}migrateGraphSelection(s);if(s.workspaceUI)s.workspaceUI=normalizeWorkspaceUI(s.workspaceUI);s.graphDates=s.graphDates===true;if(s.graphPositions){s.graphPositions=Object.fromEntries(Object.entries(s.graphPositions).filter(([id,p])=>/^-?[012]:T[1-9A-HJ-NP-Za-km-z]{33}$/.test(id)&&p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&Math.abs(p.x)<100000&&Math.abs(p.y)<100000).map(([id,p])=>[id,{x:p.x,y:p.y}]));}return s;}
$('#file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100*1024*1024)throw Error('Limite de importação: 100 MB');const envelope=JSON.parse(await file.text());if(envelope.format!=='observatorio-tron'||typeof envelope.payload!=='string')throw Error('Formato incompatível');if(hex(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(envelope.payload)))!==envelope.sha256)throw Error('SHA-256 divergente');const incoming=validateImport(JSON.parse(envelope.payload));incoming.receipts={};if(!confirm('Substituir o caso atual pelo backup? Exporte antes se precisar preservá-lo.'))return;state=incoming;selection=null;selectedNodes.clear();positions.clear();await save();$('#timezone').value=state.timezone;$('#auto').checked=state.auto;populateEmailConfig();restoreWorkspaceUI();render();toast('Caso importado. Integridade do arquivo verificada.');}catch(err){toast('Importação recusada: '+err.message);}finally{e.target.value='';}};
setInterval(()=>{if(state.auto&&!document.hidden)sync();},300000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.auto&&Date.now()-(state.last||0)>300000)sync();});window.addEventListener('unhandledrejection',e=>toast('Operação interrompida: '+e.reason?.message));init().catch(e=>toast('Armazenamento indisponível: '+e.message));
